using Point2d = cg3::Point2<double>;

std::vector<Point2d> convexHull2D(const std::vector<Point2d>& points) {
    if (points.size() <= 1) {
        return points;
    }

    // Copy points to avoid modifying the original vector
    std::vector<Point2d> pts = points;

    // Sort points lexicographically
    std::sort(pts.begin(), pts.end(), [](const Point2d& a, const Point2d& b) {
        return a.x() < b.x() || (a.x() == b.x() && a.y() < b.y());
    });

    // Remove duplicates
    auto last = std::unique(pts.begin(), pts.end());
    pts.erase(last, pts.end());

    if (pts.size() <= 2) {
        return pts;
    }

    std::vector<Point2d> hull;
    hull.reserve(pts.size() + 1);

    // Build lower hull
    for (const auto& p : pts) {
        while (hull.size() >= 2) {
            Point2d a = hull[hull.size() - 2];
            Point2d b = hull[hull.size() - 1];
            // Cross product of vectors (b - a) and (p - a)
            double cross = (b - a).perpendicularDot(p - a);
            if (cross > 0) {
                break; // Left turn
            }
            hull.pop_back();
        }
        hull.push_back(p);
    }

    // Build upper hull
    size_t lower_hull_size = hull.size();
    for (auto it = pts.rbegin() + 1; it != pts.rend(); ++it) {
        const auto& p = *it;
        while (hull.size() > lower_hull_size) {
            Point2d a = hull[hull.size() - 2];
            Point2d b = hull[hull.size() - 1];
            // Cross product of vectors (b - a) and (p - a)
            double cross = (b - a).perpendicularDot(p - a);
            if (cross > 0) {
                break; // Left turn
            }
            hull.pop_back();
        }
        hull.push_back(p);
    }

    // Remove duplicate starting point
    hull.pop_back();

    return hull;
}

